struct Doc {
    std::string text;  // owns its own buffer
};

Doc* d = new Doc{std::string(100, 'x')};

delete d;
// 1. ~Doc() runs: text frees its buffer
// 2. Doc's own memory is released

int* a = new int(1);
std::free(a);                 // new + free

int* b = (int*)std::malloc(sizeof(int));
delete b;                     // malloc + delete

int* c = new int[4];
delete c;                     // new[] needs delete[]

int* n = nullptr;
delete n;                     // no-op
std::free(nullptr);           // no-op
